(222, 94, '_wp_attachment_metadata', 'a:5:{s:5:\"width\";i:2017;s:6:\"height\";i:1986;s:4:\"file\";s:38:\"2020/06/cropped-Logo-Wanze-Bas-Oha.png\";s:5:\"sizes\";a:7:{s:6:\"medium\";a:4:{s:4:\"file\";s:38:\"cropped-Logo-Wanze-Bas-Oha-300x295.png\";s:5:\"width\";i:300;s:6:\"height\";i:295;s:9:\"mime-type\";s:9:\"image/png\";}s:5:\"large\";a:4:{s:4:\"file\";s:40:\"cropped-Logo-Wanze-Bas-Oha-1024x1008.png\";s:5:\"width\";i:1024;s:6:\"height\";i:1008;s:9:\"mime-type\";s:9:\"image/png\";}s:9:\"thumbnail\";a:4:{s:4:\"file\";s:38:\"cropped-Logo-Wanze-Bas-Oha-150x150.png\";s:5:\"width\";i:150;s:6:\"height\";i:150;s:9:\"mime-type\";s:9:\"image/png\";}s:12:\"medium_large\";a:4:{s:4:\"file\";s:38:\"cropped-Logo-Wanze-Bas-Oha-768x756.png\";s:5:\"width\";i:768;s:6:\"height\";i:756;s:9:\"mime-type\";s:9:\"image/png\";}s:9:\"1536x1536\";a:4:{s:4:\"file\";s:40:\"cropped-Logo-Wanze-Bas-Oha-1536x1512.png\";s:5:\"width\";i:1536;s:6:\"height\";i:1512;s:9:\"mime-type\";s:9:\"image/png\";}s:16:\"leto-large-thumb\";a:4:{s:4:\"file\";s:38:\"cropped-Logo-Wanze-Bas-Oha-780x768.png\";s:5:\"width\";i:780;s:6:\"height\";i:768;s:9:\"mime-type\";s:9:\"image/png\";}s:17:\"leto-medium-thumb\";a:4:{s:4:\"file\";s:38:\"cropped-Logo-Wanze-Bas-Oha-400x394.png\";s:5:\"width\";i:400;s:6:\"height\";i:394;s:9:\"mime-type\";s:9:\"image/png\";}}s:10:\"image_meta\";a:12:{s:8:\"aperture\";s:1:\"0\";s:6:\"credit\";s:0:\"\";s:6:\"camera\";s:0:\"\";s:7:\"caption\";s:0:\"\";s:17:\"created_timestamp\";s:1:\"0\";s:9:\"copyright\";s:0:\"\";s:12:\"focal_length\";s:1:\"0\";s:3:\"iso\";s:1:\"0\";s:13:\"shutter_speed\";s:1:\"0\";s:5:\"title\";s:0:\"\";s:11:\"orientation\";s:1:\"0\";s:8:\"keywords\";a:0:{}}}'),
