egoryBreakpoints[params.categoryImageSize];\n			setAttributes(categoryGrids, categoryBreakpoints);\n		}\n\n		function checkLayout() {\n			checkProductGridsLayout();\n			checkCategoryGridsLayout();\n		}\n\n		function setCellInterval(p, c) {\n			var style = document.getElementById(\'customCss\') || document.createElement(\'div\');\n			style.id = \'customCss\';\n			document.body.appendChild(style);\n\n			var css = \'\';\n			if (+p == p && p != \"\" ) {\n				p = +p;\n				css += \'.ec-size .ec-store .grid__products { margin-left: -\' + Math.max(0, p/2 - .4) + \'px; margin-right: -\' + p/2 + \'px; }\';\n				css += \'.ec-size .ec-store .grid__products .grid-product__wrap { padding: \' + p/2 + \'px; }\';\n\n				css += \'.ec-size:not(.ec-size--s) .ec-store .grid__products { margin-left: -\' + Math.max(0, Math.min(16, p) / 2 - .4) + \'px; margin-right: -\' + Math.min(16, p) / 2 + \'px; }\';\n				css += \'.ec-size:not(.ec-size--s) .ec-store .grid__products .grid-product__wrap { padding: \' + Math.min(16, p) / 2 + \'px; }\';\n			}\n\n			if (+c == c && c != \"\") {\n				c = +c;\n				css += \'.ec-size .ec-store .grid__categories { margin-left: -\' + Math.max(0, c/2 - .4) + \'px; margin-right: -\' + c/2 + \'px; }\';\n				css += \'.ec-size .ec-store .grid-category__wrap { padding: \' + c/2 + \'px; }\';\n\n				css += \'.ec-size:not(.ec-size--s) .ec-store .grid__categories { margin-left: -\' + Math.max(0, Math.min(16, c) / 2 - .4) + \'px; margin-right: -\' + Math.min(16, c) / 2 + \'px; }\';\n				css += \'.ec-size:not(.ec-size--s) .ec-store .grid__categories .grid-category__wrap { padding: \' + Math.min(16, c) / 2 + \'px; }\';\n			}\n\n			style.innerHTML = \'<style>\' + css + \'</style>\';\n		}\n\n		function init() {\n			setCellInterval(params.productCellSpacing, params.categoryCellSpacing);\n			checkLayout();\n			window.addEventListener(\'resize\', function() {\n				checkLayout();\n			});\n		}\n\n		init();\n	};\n\n	var ecwidContainer = document.querySelector(\'.ec-static-container .ec-size\');\n	var breakpoints = {\n		320: \'ec-size--xxs\',\n		414: \'ec-size--xs\',\n		480: \'ec-size--s\',\n		768: \'ec-size--m\',\n		1024: \'ec-size--l\',\n		1100: \'ec-size--xl\',\n		1440: \'ec-size--xxl\'\n	};\n\n	function onResize() {\n		var w = ecwidContainer.offsetWidth;\n		for (var i in breakpoints) {\n			if (w >= i) {\n				ecwidContainer.classList.add(breakpoints[i]);\n			}\n			else {\n				ecwidContainer.classList.remove(breakpoints[i]);\n			}\n		}\n	}\n	onResize();\n	window.addEventListener(\'load\', onResize);\n	window.addEventListener(\'resize\', onResize);\n\n	var links = document.querySelectorAll(\".ec-static-container a\");\n	for (var i = 0; i < links.length; i++) {\n		var link = links[i];\n		link.addEventListener(\'click\',function(){\n			document.querySelector(\'.ec-static-container\').classList.add(\"ec-static-container__wait\");\n		})\n	}\n\n	var grid = new Grid();\n\n})();\n\";s:19:\"metaDescriptionHtml\";s:34:\"        <title>Marksports</title>\n\";s:12:\"canonicalUrl\";s:0:\"\";s:10:\"ogTagsHtml\";s:0:\"\";s:10:\"jsonLDHtml\";s:0:\"\";s:11:\"lastUpdated\";i:1591349823452;}}', 'no');
